import * as React from "react"
import { cn } from "@/lib/utils"

interface NocGridProps extends React.HTMLAttributes<HTMLDivElement> {
  columns?: 2 | 3 | 4
}

export function NocGrid({ 
  className, 
  columns = 3,
  children,
  ...props 
}: NocGridProps) {
  return (
    <div 
      className={cn("grid gap-2 rounded-md p-3.5", className)}
      style={{
        gridTemplateColumns: `repeat(${columns}, 1fr)`,
        background: "rgba(10, 15, 20, 0.9)",
        border: "1px solid var(--border-bright, var(--border))",
      }}
      {...props}
    >
      {children}
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"
import "./noc-effects.css"

interface NocHeaderProps extends React.HTMLAttributes<HTMLDivElement> {
  label?: string
}

export function NocHeader({ 
  className, 
  label = "// MOCKUP · NOC_01",
  ...props 
}: NocHeaderProps) {
  return (
    <div 
      className={cn("flex items-center gap-2 px-4 py-2 border-b font-mono text-[10px] tracking-widest", className)}
      style={{
        background: "var(--surface-2, var(--muted))",
        borderBottomColor: "var(--border-bright, var(--border))",
        color: "var(--fg, var(--foreground))",
      }}
      {...props}
    >
      <div 
        className="w-1.5 h-1.5 rounded-full"
        style={{
          background: "var(--ok, #3ddc84)",
          boxShadow: "0 0 6px var(--ok, #3ddc84)",
          animation: "noc-pulse 1.6s ease-in-out infinite",
        }}
      />
      {label}
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

interface NocTileProps extends React.HTMLAttributes<HTMLDivElement> {
  label?: string
  value?: string
  unit?: string
}

export function NocTile({ 
  className, 
  label = "CPU",
  value = "42%",
  unit = "▲ stable",
  ...props 
}: NocTileProps) {
  return (
    <div 
      className={cn(
        "border rounded p-2.5 min-h-[40px] flex flex-col justify-center gap-0.5 font-mono",
        className
      )}
      style={{
        background: "var(--surface, var(--card))",
        borderColor: "var(--border, #2a2a32)",
      }}
      {...props}
    >
      <div 
        className="tracking-wider text-[9px] uppercase"
        style={{ color: "var(--fg-dim, var(--muted-foreground))" }}
      >
        {label}
      </div>
      <div 
        className="text-[22px] font-bold leading-tight"
        style={{ color: "var(--accent-2, #00ff66)" }}
      >
        {value}
      </div>
      {unit && (
        <div 
          className="tracking-wide text-[9px]"
          style={{ color: "var(--ok, #3ddc84)" }}
        >
          {unit}
        </div>
      )}
    </div>
  )
}
